import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cstdint>

__global__ void conv_transpose2d_gather_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const long long total,
    const int batch,
    const int C_in,
    const int H_in,
    const int W_in,
    const int C_out,
    const int H_out,
    const int W_out,
    const int kH,
    const int kW,
    const int stride_h,
    const int stride_w,
    const int pad_h,
    const int pad_w,
    const int dil_h,
    const int dil_w,
    const int groups) {
  const long long idx0 = (long long)blockIdx.x * blockDim.x + threadIdx.x;
  const long long step = (long long)gridDim.x * blockDim.x;

  const int C_out_pg = C_out / groups;
  const int C_in_pg = C_in / groups;
  const long long in_hw = (long long)H_in * W_in;
  const long long out_hw = (long long)H_out * W_out;
  const long long w_oc_stride = (long long)kH * kW;
  const long long w_ic_stride = (long long)C_out_pg * kH * kW;

  for (long long idx = idx0; idx < total; idx += step) {
    long long t = idx;
    const int ow = (int)(t % W_out);
    t /= W_out;
    const int oh = (int)(t % H_out);
    t /= H_out;
    const int oc = (int)(t % C_out);
    const int n = (int)(t / C_out);

    const int g = oc / C_out_pg;
    const int oc_local = oc - g * C_out_pg;
    const int ic0 = g * C_in_pg;

    float acc = (bias != nullptr) ? __ldg(bias + oc) : 0.0f;

    for (int kh = 0; kh < kH; ++kh) {
      const int num_h = oh + pad_h - kh * dil_h;
      if (num_h < 0) continue;
      if ((num_h % stride_h) != 0) continue;
      const int ih = num_h / stride_h;
      if (ih < 0 || ih >= H_in) continue;

      for (int kw = 0; kw < kW; ++kw) {
        const int num_w = ow + pad_w - kw * dil_w;
        if (num_w < 0) continue;
        if ((num_w % stride_w) != 0) continue;
        const int iw = num_w / stride_w;
        if (iw < 0 || iw >= W_in) continue;

        const float* x_ptr =
            input + (((long long)n * C_in + ic0) * in_hw + (long long)ih * W_in + iw);
        const float* w_ptr =
            weight + (((long long)ic0 * C_out_pg + oc_local) * w_oc_stride + (long long)kh * kW + kw);

        for (int r = 0; r < C_in_pg; ++r) {
          const float xv = __ldg(x_ptr + (long long)r * in_hw);
          const float wv = __ldg(w_ptr + (long long)r * w_ic_stride);
          acc += xv * wv;
        }
      }
    }

    output[idx] = acc;
  }
}

torch::Tensor conv_transpose2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    const c10::optional<torch::Tensor>& bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w,
    int64_t groups) {
  TORCH_CHECK(input.is_cuda(), "input must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
  TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
  TORCH_CHECK(input.dim() == 4, "input must be NCHW");
  TORCH_CHECK(weight.dim() == 4, "weight must be (C_in, C_out/groups, kH, kW)");
  TORCH_CHECK(stride_h > 0 && stride_w > 0, "stride must be positive");
  TORCH_CHECK(dil_h > 0 && dil_w > 0, "dilation must be positive");
  TORCH_CHECK(groups > 0, "groups must be positive");

  const int64_t batch = input.size(0);
  const int64_t C_in = input.size(1);
  const int64_t H_in = input.size(2);
  const int64_t W_in = input.size(3);

  const int64_t kH = weight.size(2);
  const int64_t kW = weight.size(3);
  const int64_t C_out_pg = weight.size(1);
  TORCH_CHECK(weight.size(0) == C_in, "weight in_channels mismatch");
  TORCH_CHECK(C_in % groups == 0, "C_in must be divisible by groups");
  const int64_t C_out = C_out_pg * groups;

  const int64_t H_out = (H_in - 1) * stride_h - 2 * pad_h + dil_h * (kH - 1) + 1;
  const int64_t W_out = (W_in - 1) * stride_w - 2 * pad_w + dil_w * (kW - 1) + 1;
  TORCH_CHECK(H_out > 0 && W_out > 0, "invalid output size");
  TORCH_CHECK(H_in < INT32_MAX && W_in < INT32_MAX && H_out < INT32_MAX && W_out < INT32_MAX,
              "tensor too large for int32 coordinates");

  auto input_c = input.contiguous();
  auto weight_c = weight.contiguous();

  const bool has_bias = bias.has_value();
  torch::Tensor bias_c;
  const float* bias_ptr = nullptr;
  if (has_bias) {
    bias_c = bias->contiguous();
    TORCH_CHECK(bias_c.is_cuda(), "bias must be CUDA");
    TORCH_CHECK(bias_c.scalar_type() == torch::kFloat32, "bias must be float32");
    TORCH_CHECK(bias_c.numel() == C_out, "bias has wrong shape");
    bias_ptr = bias_c.data_ptr<float>();
  }

  auto output = torch::empty({batch, C_out, H_out, W_out}, input_c.options());
  const long long total = (long long)batch * C_out * H_out * W_out;
  if (total == 0) return output;

  const int threads = 256;
  const long long blocks_ll = (total + threads - 1) / threads;
  const unsigned int blocks = (unsigned int)std::min<long long>(blocks_ll, 2147483647LL);

  cudaStream_t stream = at::cuda::getCurrentCUDAStream();
  conv_transpose2d_gather_kernel<<<blocks, threads, 0, stream>>>(
      input_c.data_ptr<float>(),
      weight_c.data_ptr<float>(),
      bias_ptr,
      output.data_ptr<float>(),
      total,
      (int)batch,
      (int)C_in,
      (int)H_in,
      (int)W_in,
      (int)C_out,
      (int)H_out,
      (int)W_out,
      (int)kH,
      (int)kW,
      (int)stride_h,
      (int)stride_w,
      (int)pad_h,
      (int)pad_w,
      (int)dil_h,
      (int)dil_w,
      (int)groups);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return output;
}
"""

_cpp_src = r"""
torch::Tensor conv_transpose2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    const c10::optional<torch::Tensor>& bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w,
    int64_t groups);
"""

_ext = load_inline(
    name="custom_conv_transpose2d_gather",
    cpp_sources=[_cpp_src],
    cuda_sources=[_cuda_src],
    functions=["conv_transpose2d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1),
        padding: tuple = (0, 0),
        dilation: tuple = (1, 1),
        groups: int = 1,
        bias: bool = False,
    ):
        super(ModelNew, self).__init__()
        self.stride_h, self.stride_w = int(stride[0]), int(stride[1])
        self.pad_h, self.pad_w = int(padding[0]), int(padding[1])
        self.dil_h, self.dil_w = int(dilation[0]), int(dilation[1])
        self.groups = int(groups)

        # Parameter container only; forward uses the custom CUDA kernel above.
        self.conv_transpose2d = nn.ConvTranspose2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _ext.conv_transpose2d_forward(
            x,
            self.conv_transpose2d.weight,
            self.conv_transpose2d.bias,
            self.stride_h,
            self.stride_w,
            self.pad_h,
            self.pad_w,
            self.dil_h,
            self.dil_w,
            self.groups,
        )

